41	const CONV_INDEX_KEY = 'mia_conversations';
42	const CONV_MSG_PREFIX = 'mia_conv_';
43	const ACTIVE_KEY = 'mia_active_conv';
44	const OPEN_KEY = 'mia_panel_open';
