54	function loadConversations(): MiaConversation[] {
55	  try {
56	    const raw = localStorage.getItem(CONV_INDEX_KEY);
57	    return raw ? JSON.parse(raw) : [];
58	  } catch { return []; }
59	}
60	
61	function saveConversations(convs: MiaConversation[]) {
62	  try { localStorage.setItem(CONV_INDEX_KEY, JSON.stringify(convs)); } catch {}
63	}
64	
65	function loadConversationMessages(convId: string): MiaChatMessage[] {
66	  try {
67	    const raw = localStorage.getItem(CONV_MSG_PREFIX + convId);
68	    if (!raw) return [];
69	    return JSON.parse(raw).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) }));
70	  } catch { return []; }
71	}
72	
73	// Comprime histórico para localStorage: >10 msgs → mantém 6 recentes + 1 placeholder de compressão
74	function compressHistory(msgs: MiaChatMessage[]): MiaChatMessage[] {
75	  if (msgs.length <= 10) return msgs;
76	  const recent = msgs.slice(-6);
77	  const olderCount = msgs.length - 6;
78	  const summaryMsg: MiaChatMessage = {
79	    id: 'history-summary',
80	    role: 'assistant',
81	    content: `[${olderCount} mensagens anteriores comprimidas para economizar espaço]`,
82	    timestamp: msgs[0]?.timestamp || new Date(),
83	  };
84	  return [summaryMsg, ...recent];
85	}
86	
87	function saveConversationMessages(convId: string, messages: MiaChatMessage[]) {
88	  try {
89	    const toSave = compressHistory(messages);
90	    const serialized = toSave.map(m => ({
91	      id: m.id, role: m.role, content: m.content,
92	      actions: m.actions, actionsExecuted: m.actionsExecuted,
93	      thinkingBlocks: m.thinkingBlocks,
94	      agentRounds: m.agentRounds,
95	      executionStepsSnapshot: m.executionStepsSnapshot,
96	      watchLogSnapshot: m.watchLogSnapshot,
97	      clarification: m.clarification,
