124	// ============================================================================
125	// MODULE VISIT TRACKING — rastreia primeira visita para onboarding
126	// ============================================================================
127	
128	const MODULE_VISITS_KEY = 'mia_module_visits';
129	
130	function loadModuleVisits(): Record<string, { count: number; first_visit: string; last_visit: string }> {
131	  try {
132	    const raw = localStorage.getItem(MODULE_VISITS_KEY);
133	    return raw ? JSON.parse(raw) : {};
134	  } catch { return {}; }
135	}
136	
137	function trackModuleVisit(route: string) {
138	  try {
139	    const visits = loadModuleVisits();
140	    const now = new Date().toISOString().split('T')[0];
141	    const existing = visits[route];
142	    visits[route] = {
143	      count: (existing?.count || 0) + 1,
144	      first_visit: existing?.first_visit || now,
145	      last_visit: now,
146	    };
147	    localStorage.setItem(MODULE_VISITS_KEY, JSON.stringify(visits));
148	  } catch {}
149	}
150	
151	function buildUserProfile(user: any, route: string): MiaUserProfile {
152	  const visits = loadModuleVisits();
153	  const totalVisits = Object.values(visits).reduce((sum, v) => sum + v.count, 0);
154	
155	  let role: MiaUserProfile['role'] = 'unknown';
156	  const userRole = user?.user_metadata?.role || user?.app_metadata?.role || '';
157	  if (userRole === 'admin' || userRole === 'super_admin') role = 'admin';
158	  else if (userRole === 'gerente' || userRole === 'manager') role = 'gerente';
159	  else if (userRole === 'operador' || userRole === 'operator') role = 'operador';
160	  else if (userRole === 'diretoria' || userRole === 'director') role = 'diretoria';
161	
162	  let expertise_level: MiaUserProfile['expertise_level'] = 'beginner';
163	  if (totalVisits > 50) expertise_level = 'advanced';
164	  else if (totalVisits > 15) expertise_level = 'intermediate';
165	
166	  return {
167	    role,
168	    name: user?.user_metadata?.full_name || user?.user_metadata?.name || undefined,
169	    expertise_level,
170	    module_visits: visits,
171	  };
172	}
