367	  // ── Cross-device sync (DB é source-of-truth, localStorage é cache offline) ──
368	  //
369	  // Estratégia world-class:
370	  // 1. Boot/login: carrega lista do DB. Se a activeConversationId local não
371	  //    está no DB (ex: foi criada offline ou em outro device que não sincou
372	  //    ainda), switcha pra conversa mais recente do DB. Garante que ao abrir
373	  //    em qualquer device, o user vê a continuação real, não uma conversa
374	  //    fantasma local.
375	  // 2. Sempre que o painel abre (isOpen=true): re-sincroniza lista + mensagens
376	  //    da conversa ativa. Pega edições feitas em outro device.
377	  // 3. Realtime subscription: postgres_changes em chat_messages do user vivo.
378	  //    Quando outro device escreve, esse device atualiza messages na hora.
379	  //
380	  // Resultado: histórico = mesmo em todos os devices, ordem temporal correta.
381	  const lastSyncedAtRef = useRef<number>(0);
382	  const SYNC_THROTTLE_MS = 2_000;
383	
384	  const syncFromDb = useCallback(async (opts?: { force?: boolean; switchToLatestIfMissing?: boolean }) => {
385	    if (!user?.id) return;
386	    const now = Date.now();
387	    if (!opts?.force && now - lastSyncedAtRef.current < SYNC_THROTTLE_MS) return;
388	    lastSyncedAtRef.current = now;
389	    try {
390	      const dbConvs = await listUserConversations(user.id, 50);
391	      if (dbConvs.length > 0) {
