395	            byId.set(dbc.id, {
396	              id: dbc.id,
397	              title: dbc.title,
398	              createdAt: dbc.createdAt,
399	              updatedAt: dbc.updatedAt,
400	              messageCount: Math.max(dbc.messageCount, byId.get(dbc.id)?.messageCount ?? 0),
401	            });
402	          }
403	          return [...byId.values()].sort(
404	            (a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
405	          );
406	        });
407	
408	        // Se a activeConversationId local não existe no DB, é uma conv local
409	        // sem persistência. Em fresh device é o caso comum. Switcha pra latest.
410	        if (opts?.switchToLatestIfMissing) {
411	          const activeIsInDb = dbConvs.some(c => c.id === activeConversationId);
412	          const localHasMessages = messages.length > 0;
413	          if (!activeIsInDb && !localHasMessages) {
414	            const latest = dbConvs[0];
415	            setActiveConversationId(latest.id);
416	            setActiveConvId(latest.id);
417	            const dbMsgs = await loadConversationMessagesFromDB(latest.id, user.id, 200);
418	            setMessages(dbMsgs);
419	            return;
420	          }
421	        }
422	      }
423	
424	      if (activeConversationId) {
425	        const dbMsgs = await loadConversationMessagesFromDB(activeConversationId, user.id, 200);
426	        if (dbMsgs.length > 0) {
427	          // DB vence se tem mais histórico (outro device escreveu) ou se o
428	          // último timestamp do DB é mais novo que o local.
429	          setMessages(current => {
430	            if (dbMsgs.length > current.length) return dbMsgs;
431	            const lastDb = dbMsgs[dbMsgs.length - 1]?.timestamp?.getTime() ?? 0;
432	            const lastLocal = current[current.length - 1]?.timestamp?.getTime() ?? 0;
433	            if (lastDb > lastLocal) return dbMsgs;
434	            return current;
435	          });
436	        }
437	      }
438	    } catch (e) {
439	      console.warn('[mia] sync from DB failed', e);
440	    }
441	  }, [user?.id, activeConversationId, messages.length]);
442	
443	  // Boot: ao logar (user.id muda), faz sync agressivo + switch se necessário.
