564	
565	  // ── Destaque de elemento (modo tutor) ─────────────────────
566	
567	  const highlightElement = useCallback((selector: string, durationMs = 3000) => {
568	    try {
569	      const el = document.querySelector(selector) as HTMLElement | null;
570	      if (!el) return;
