27	// ─── Slot pra renderizar clarification_form do backend (Claude AskUserQuestion)
28	function ClarificationSlot() {
29	  const { sendMessage } = useMia();
30	  const [form, setForm] = useState<ClarificationForm | null>(null);
31	
32	  useEffect(() => {
33	    const handler = (e: Event) => {
34	      const detail = (e as CustomEvent<ClarificationForm>).detail;
35	      if (detail && Array.isArray(detail.questions) && detail.questions.length > 0) {
36	        setForm(detail);
37	        // Flag global: modais protegidos checam isso pra NÃO fechar enquanto
38	        // MIA aguarda esclarecimento. Sem isso, click em option do form
39	        // era interpretado como "outside click" → modal NF fechava.
40	        try {
41	          document.documentElement.setAttribute('data-mia-clarification-pending', 'true');
42	        } catch { /* noop */ }
43	      }
44	    };
45	    window.addEventListener('mia:clarification-form', handler);
46	    return () => {
47	      window.removeEventListener('mia:clarification-form', handler);
48	      try { document.documentElement.removeAttribute('data-mia-clarification-pending'); } catch {}
49	    };
50	  }, []);
51	
52	  // Limpa flag quando form é fechado/respondido
53	  useEffect(() => {
54	    if (!form) {
55	      try { document.documentElement.removeAttribute('data-mia-clarification-pending'); } catch {}
56	    }
57	  }, [form]);
58	
59	  if (!form) return null;
60	  return (
61	    <MiaClarificationDialog
62	      form={form}
63	      // CRÍTICO: onSubmit recebe o responseText e DISPARA sendMessage —
64	      // sem isso, MIA não recebia a resposta e o fluxo morria. Antes
65	      // estava `() => setForm(null)` que descartava o texto.
66	      //
67	      // ORDEM: sendMessage PRIMEIRO (dispara POST async — isStreaming sobe
68	      // assim que primeira resposta SSE chega), só DEPOIS setForm(null).
69	      // Sem essa ordem, a flag data-mia-clarification-pending era removida
70	      // antes do miaActive subir → janela de race onde modal NF voltava
71	      // a ser fully modal → blocking de clicks na MIA pane.
72	      onSubmit={(responseText) => {
73	        sendMessage(responseText);
74	        setForm(null);
75	      }}
76	      onCancel={() => setForm(null)}
77	    />
78	  );
79	}
