38	function loadPaneSize(): number {
39	  try {
40	    const saved = localStorage.getItem(MIA_PANE_SIZE_KEY);
41	    const n = saved ? parseInt(saved, 10) : 33;
42	    if (Number.isFinite(n) && n >= 20 && n <= 60) return n;
43	    return 33;
44	  } catch { return 33; }
