55	function loadWatchLog(): MiaWatchLogEntry[] {
56	  try {
57	    const raw = localStorage.getItem(MIA_WATCHLOG_KEY);
58	    if (!raw) return [];
59	    const parsed = JSON.parse(raw);
60	    if (!Array.isArray(parsed)) return [];
61	    // Last entry "in_progress" stale ao recarregar — sanitiza pra 'info'
62	    // pra evitar isExecuting ficar travado em true pós-reload.
63	    return parsed.slice(-200).map((e: any, i: number, arr: any[]) => {
64	      if (i === arr.length - 1 && e.status === 'in_progress') {
65	        return { ...e, status: 'info' as const };
66	      }
67	      return e;
68	    });
69	  } catch { return []; }
70	}
