72	function loadRecordedActions(): MiaRecordedAction[] {
73	  try {
74	    const raw = localStorage.getItem(MIA_RECORDED_KEY);
75	    if (!raw) return [];
76	    const parsed = JSON.parse(raw);
77	    return Array.isArray(parsed) ? parsed.slice(-100) : [];
78	  } catch { return []; }
79	}
